edits:
/* Compact touch HUD: one fixed-width row, with no nested positioning or blur. */
:root{--safe-left:env(safe-area-inset-left,0px);--safe-right:env(safe-area-inset-right,0px)}
#loadoutBar{position:absolute;left:50%;bottom:calc(12px + var(--safe-bottom));transform:translateX(-50%);display:flex;align-items:center;gap:6px;pointer-events:none;max-width:calc(100vw - 20px - var(--safe-left) - var(--safe-right))}
#actionBar,.is-touch #actionBar,#weaponDock,.is-touch #weaponDock{position:static;inset:auto;transform:none;max-width:none;display:flex;gap:5px;padding:0;border:0;background:none;overflow:visible;pointer-events:none;border-radius:0}
#loadoutBar button{flex-shrink:0;height:48px;min-height:48px;background:rgba(19,30,24,.4);border:1px solid rgba(223,238,190,.32);border-radius:5px;padding:5px;box-shadow:none;backdrop-filter:none;touch-action:manipulation}
#loadoutBar button:hover{background:rgba(32,47,35,.55)}
#actionBar button{width:48px;min-width:48px}
#actionBar small{font:700 7px ui-monospace,monospace;letter-spacing:0;white-space:nowrap;margin-top:4px;color:#f1f1de}
#actionBar .action-symbol{font-size:18px;line-height:18px}
#weaponDock .weapon-slot.main{width:76px;min-width:76px;border-color:#d4e98299;background:rgba(74,86,43,.28)}
#weaponDock .weapon-slot.more-slot{width:46px;min-width:46px}
#weaponDock .weapon-slot svg{width:61px;height:21px;margin:0 auto}
#weaponDock .weapon-name{font-size:7px;line-height:10px;color:#eff1dc}
#weaponDock .ammo{font-size:9px;line-height:10px}
#weaponDock .more-slot .ammo{display:none}
#weaponDock .more-slot .action-symbol{font-size:23px;line-height:23px}
#weaponDock .key{display:none}
.stick,.is-touch .stick{width:114px;height:114px;bottom:calc(12px + var(--safe-bottom))}
.left-stick{left:calc(14px + var(--safe-left))}.right-stick{right:calc(14px + var(--safe-right))}
.stick-ring{inset:4px;background:rgba(190,211,142,.05);border:1px solid rgba(220,234,186,.28);box-shadow:none}
.stick-ring i{width:38px;height:38px;background:rgba(213,232,171,.19);border:1px solid rgba(219,235,184,.5);box-shadow:none}
.stick-ring span{font-size:7px;bottom:10px;color:#f1f1ddbb}
.hud-top{top:calc(5px + var(--safe-top));left:calc(12px + var(--safe-left));right:calc(12px + var(--safe-right));background:none;padding:0;gap:8px}
.vitals{width:145px;padding-top:3px}.health-bar{height:6px;margin:5px 0;background:#13221a55}
.wave-readout{gap:2px}.wave-readout>strong{font-size:23px}.wave-readout .tiny{font-size:7px}
.hud-right{gap:10px}.score-readout>strong{font-size:18px}.score-readout>span:last-child{font-size:10px}
.icon-button{width:44px;height:44px;min-height:44px;background:rgba(20,32,24,.34);border-color:#c7d69d55}
.combo-readout{top:calc(58px + var(--safe-top));font-size:9px}.combo-readout>div{width:70px;margin-top:3px;background:#172b2255}
.save-indicator{right:calc(13px + var(--safe-right));bottom:calc(4px + var(--safe-bottom));font-size:6px}
#toast{top:calc(87px + var(--safe-top));font-size:10px;padding:7px 12px;background:#19281fd9}
#desktopHint{bottom:calc(69px + var(--safe-bottom));font-size:8px;background:none;max-width:95vw;white-space:normal;text-align:center}
.map-info em{display:block;font:normal 8px ui-monospace,monospace;color:#efbe88;margin-top:5px}
.map-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.map-card canvas{max-height:none}
.shop-art{height:88px;background:radial-gradient(ellipse at center,#46543a55,transparent 70%),#14221a}
.shop-art svg{width:90%;max-width:200px;height:72px;filter:drop-shadow(0 4px 2px #0007)}
#panel .shop-card h3{text-transform:none;letter-spacing:0}
@media(max-width:600px){
 .vitals{width:102px}.hud-label{font-size:7px;letter-spacing:.5px}.hud-label strong{font-size:8px}
 .score-readout>strong{font-size:14px}.hud-right{gap:5px}.wave-readout>strong{font-size:22px}
 .vitals .tiny,.wave-readout .tiny{font-size:6px}.hud-top{left:calc(8px + var(--safe-left));right:calc(8px + var(--safe-right))}
 .map-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.shop-art{height:76px}.shop-art svg{height:64px}
}
@media(orientation:portrait){
 .stick,.is-touch .stick{bottom:calc(75px + var(--safe-bottom));width:116px;height:116px}
 #loadoutBar{bottom:calc(12px + var(--safe-bottom))}
 #toast{top:calc(85px + var(--safe-top))}.combo-readout{top:calc(58px + var(--safe-top))}
}
@media(orientation:landscape) and (max-height:550px){
 #loadoutBar{bottom:calc(10px + var(--safe-bottom))}
 .stick,.is-touch .stick{width:108px;height:108px;bottom:calc(8px + var(--safe-bottom))}
 .dialog-head{padding:9px 16px}.dialog-head h2{font-size:21px}.dialog-body{padding:12px 16px}
 .dialog-foot{padding:8px 16px}.dialog-foot button{min-height:44px}.shop-tabs button{min-height:44px}
 .map-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.map-card canvas{max-height:86px}
 .shop-art{height:70px}.shop-art svg{height:60px}.combo-readout{top:calc(57px + var(--safe-top))}
}
